namespace CourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematical sciences." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and fundamental forces." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace has 15 years of experience teaching introductory computer science and is passionate about making programming accessible to all students.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing specializes in algorithm complexity theory and has published extensively on efficient data processing.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd's research focuses on relational data models and query optimization.", DepartmentId = "cs" },
        new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Euler Bernoulli", InstructorBio = "Dr. Bernoulli brings 20 years of experience in mathematical analysis and has authored three widely-used textbooks.", DepartmentId = "math", IsFeatured = true },
        new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is a renowned algebraist whose research spans abstract algebra and theoretical physics applications.", DepartmentId = "math" },
        new() { Id = 6, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop critical writing skills through essay composition, argument construction, and rhetorical analysis.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is an award-winning author and writing instructor with a focus on narrative structure and voice.", DepartmentId = "eng", IsFeatured = true },
        new() { Id = 7, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Mark Twain", InstructorBio = "Prof. Twain specializes in 19th-century American fiction and humor in literature.", DepartmentId = "eng" },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Marie Curie", InstructorBio = "Dr. Curie is a distinguished physicist with expertise in experimental methods and a passion for hands-on learning.", DepartmentId = "phys" },
        new() { Id = 9, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. James Maxwell", InstructorBio = "Dr. Maxwell's research focuses on electromagnetic theory and its modern applications in technology.", DepartmentId = "phys" },
        new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, events, and cultural developments from prehistory to 1500 CE.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Prof. Herodotus Smith", InstructorBio = "Prof. Smith is a specialist in ancient civilizations with field experience across Europe and the Middle East.", DepartmentId = "hist" },
        new() { Id = 11, Code = "HIST 250", Title = "Modern European History", Description = "Europe from the Enlightenment to the present: revolutions, wars, and social transformations.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Prof. Anne Frank-Miller", InstructorBio = "Prof. Frank-Miller's expertise lies in 20th-century European social history and oral history methodologies.", DepartmentId = "hist", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetAllCourses() => _courses;
}

